// Compares the TypeScript port against traces produced by Beer's original C++
// (tests/fixtures/reference.json, generated by native/build-fixtures.sh).

import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { CTRNN, parseNs } from '../src/sim/core/ctrnn';
import { RandomState } from '../src/sim/core/random';
import { localEvaluator, mapSearchParameter, TSearch, type SearchConfig } from '../src/sim/core/tsearch';
import { defaultBody, LeggedAgent, type ControllerKind } from '../src/sim/agents/legged/body';
import { decodeGenome, defaultRanges, evaluateWalker } from '../src/sim/agents/legged/walker';

const ref: any = JSON.parse(readFileSync(new URL('./fixtures/reference.json', import.meta.url), 'utf8'));

function maxRelErr(a: ArrayLike<number>, b: ArrayLike<number>): number {
  let m = 0;
  for (let i = 0; i < a.length; i++) {
    const d = Math.abs(a[i] - b[i]) / Math.max(1, Math.abs(b[i]));
    if (d > m) m = d;
  }
  return m;
}

describe('RandomState', () => {
  for (const r of ref.random) {
    it(`matches ran1/gaussian/int/choice/unit-vector for seed ${r.seed}`, () => {
      const rs = new RandomState(r.seed);
      expect(Array.from({ length: 50 }, () => rs.ran1())).toEqual(r.ran1);
      const g = Array.from({ length: 20 }, () => rs.gaussianRandom(0, 1));
      expect(maxRelErr(g, r.gaussian)).toBeLessThan(1e-14);
      expect(Array.from({ length: 20 }, () => rs.uniformRandomInteger(1, 2147483647))).toEqual(r.uniformInt);
      expect(Array.from({ length: 20 }, () => rs.probabilisticChoice(0.3))).toEqual(r.probChoice);
      const uv = new Float64Array(7);
      rs.randomUnitVector(uv);
      expect(maxRelErr(uv, r.unitVector)).toBeLessThan(1e-14);
    });
  }
});

describe('CTRNN', () => {
  for (const [name, method] of [['ctrnnEuler', 'euler'], ['ctrnnRK4', 'rk4']] as const) {
    it(`matches ${name} trajectory`, () => {
      const f = ref[name];
      const c = new CTRNN(2);
      c.biases[0] = -2.75; c.biases[1] = -1.75;
      c.setWeight(0, 0, 4.5); c.setWeight(0, 1, -1); c.setWeight(1, 0, 1); c.setWeight(1, 1, 4.5);
      c.randomizeCircuitState(-0.5, 0.5, new RandomState(1));
      const o1 = [c.outputs[0]], o2 = [c.outputs[1]];
      for (let i = 0; i < 2500; i++) {
        if (method === 'euler') c.eulerStep(0.01); else c.rk4Step(0.01);
        o1.push(c.outputs[0]); o2.push(c.outputs[1]);
      }
      expect(maxRelErr(o1, f.o1)).toBeLessThan(1e-9);
      expect(maxRelErr(o2, f.o2)).toBeLessThan(1e-9);
    });
  }

  it('parses cpg.ns-style text with CR line endings', () => {
    const p = parseNs('2\r\r1 2\r\r-1 1\r\r1.0 1.0\r\r0.5 -0.5\r3 4\r');
    expect(p).toEqual({ size: 2, taus: [1, 2], biases: [-1, 1], gains: [1, 1], weights: [0.5, -0.5, 3, 4] });
  });
});

function runFixtureWalker(f: { duration: number; dt: number; randomize: number; seed: number }, circuit: ReturnType<typeof parseNs> | null, kind: ControllerKind) {
  const ns = circuit ? CTRNN.fromParams(circuit) : new CTRNN(1);
  const a = new LeggedAgent(ns, defaultBody);
  a.reset(0, 0, !!f.randomize, new RandomState(f.seed));
  const out: Record<string, number[]> = { cx: [], angle: [], footState: [], vx: [] };
  const outputs: number[][] = Array.from({ length: ns.size }, () => []);
  let steps = 0;
  for (let t = 0; t < f.duration; t += f.dt) {
    a.step(kind, f.dt);
    steps++;
    out.cx.push(a.cx); out.angle.push(a.leg.angle); out.footState.push(a.leg.footState); out.vx.push(a.vx);
    for (let i = 0; i < ns.size; i++) outputs[i].push(ns.outputs[i]);
  }
  return { a, out, outputs, steps };
}

describe('LeggedAgent', () => {
  const cases: [string, string | null, ControllerKind][] = [
    ['walkerCpg', 'cpgCircuit', 'cpg'],
    ['walkerCpgRandomized', 'cpgCircuit', 'cpg'],
    ['walkerTwo', 'twoCircuit', 'two'],
    ['walkerOne', 'oneCircuit', 'one'],
    ['walkerPerfect', null, 'perfect'],
  ];
  for (const [name, circuitName, kind] of cases) {
    it(`matches ${name}`, () => {
      const f = ref[name];
      const circuit = circuitName ? ref[circuitName] : null;
      const { a, out, outputs, steps } = runFixtureWalker(f, circuit, kind);
      expect(steps).toBe(f.steps);
      expect(out.footState).toEqual(f.footState);
      expect(maxRelErr(out.cx, f.cx)).toBeLessThan(1e-9);
      expect(maxRelErr(out.angle, f.angle)).toBeLessThan(1e-9);
      for (let i = 0; i < outputs.length; i++) expect(maxRelErr(outputs[i], f.outputs[i])).toBeLessThan(1e-9);
      expect(a.cx / f.duration).toBeCloseTo(f.avgVelocity, 10);
    });
  }

  it("Beer's cpg.ns walks at about the optimal speed", () => {
    expect(ref.walkerCpg.avgVelocity).toBeGreaterThan(0.6);
    expect(ref.walkerPerfect.avgVelocity).toBeGreaterThan(ref.walkerCpg.avgVelocity);
  });
});

describe('TSearch', () => {
  const quad = (v: Float64Array) => {
    const p1 = mapSearchParameter(v[0], -10, 10), p2 = mapSearchParameter(v[1], -10, 10);
    return 200 - (p1 * p1 + p2 * p2);
  };
  // Must match decodeWalker in native/harness/fixtures.cpp
  const walkSpec = { controller: 'cpg' as const, size: 3, ranges: defaultRanges };
  const walkRun = { duration: 220, dt: 0.1, randomize: false, seed: 0 };
  const walker = (v: Float64Array, rs: RandomState) => evaluateWalker(decodeGenome(v, walkSpec), walkRun, rs);

  const cases: [string, (v: Float64Array, rs: RandomState) => number][] = [
    ['searchQuadHill', quad],
    ['searchQuadGA', quad],
    ['searchQuadGAFitProp', quad],
    ['searchWalkerGA', walker],
    ['searchWalkerHillReEval', walker],
  ];
  for (const [name, fn] of cases) {
    it(`matches ${name}`, async () => {
      const f = ref[name];
      const cfg: SearchConfig = {
        vectorSize: f.vectorSize, populationSize: f.pop, maxGenerations: f.gens, seed: 87632455,
        selection: f.selection, reproduction: f.mode, crossover: 'twopoint', elitistFraction: f.elite,
        maxExpectedOffspring: 1.1, mutationVariance: f.mutationVariance, crossoverProbability: 0,
        constrain: true, reEvaluate: !!f.reeval,
      };
      const s = new TSearch(cfg, localEvaluator(fn));
      await s.run();
      const best = s.generations.map((g) => g.bestSoFar);
      const avg = s.generations.map((g) => g.avg);
      expect(best.length).toBe(f.best.length);
      expect(maxRelErr(best, f.best)).toBeLessThan(1e-9);
      expect(maxRelErr(avg, f.avg)).toBeLessThan(1e-9);
      expect(maxRelErr(s.bestVector, f.bestVector)).toBeLessThan(1e-9);
    });
  }
});
